        treatment_protocol="【病態】馬喘息症候群(Equine Asthma Syndrome、Couetil et al. JVIM 2016 ACVIM Consensus)。軽度〜中等度型(IAD、Inflammatory Airway Disease):若齢〜中年競走馬、運動不耐性のみ。重度型(severe equine asthma、旧RAO/heaves):高齢馬、安静時呼吸困難、ヒーブライン形成。気道過敏性・好中球性炎症・粘液過分泌・気管支収縮。【診断】(1)BAL細胞診(ゴールドスタンダード):好中球>5%(IAD)、>25%(severe asthma)、肥満細胞>2%・好酸球>1%でも診断。(2)気管洗浄液(TTW):培養陰性で炎症のみ。(3)安静時動脈血ガス:重度型でPaO2<70 mmHg。(4)胸部X線:気管支間質性パターン、横隔膜平坦化(慢性)。(5)肺機能検査(Δpleural pressure、forced oscillometry)。【環境管理(治療の基盤)】低粉塵環境:乾草の完全浸水(30分以上)またはスチーム処理(Haygain等)、ペレット・サイレージ・カットヘイジ代替、放牧時間最大化、敷料は紙/木質ペレット(藁・木屑禁忌)、馬房換気改善、鞍庫等のホコリ源から離す。【吸入療法(第一選択)】(1)吸入コルチコステロイド(ICS):フルチカゾン(Flovent)2000-3000 μg q12h(AeroMask/AeroHIPPUS使用)、ベクロメタゾン3750-7500 μg q12h、ブデソニド1500-3000 μg q12h(ネブライザー)、新世代:吸入デキサメタゾン(Dembexin、Aservo EquiHaler 2018認可)2 puffs q12h × 10日。(2)吸入気管支拡張薬:アルブテロール(SABA)450-900 μg PRN(発作時)、サルメテロール(LABA)210 μg q12h、イプラトロピウム(SAMA)90-180 μg q6-8h。【全身療法(重症急性増悪時)】デキサメタゾン 0.05-0.1 mg/kg IV/IM/PO q24h × 3-7日 → 漸減、プレドニゾロン 1-2 mg/kg PO q24h × 7-10日 → 漸減(蹄葉炎リスク評価:EMS/PPID併発で禁忌に近い)。クレンブテロール 0.8-3.2 μg/kg PO q12h(Ventipulmin、米国EQU/競技規則注意)。【新規治療】生理食塩水ネブライゼーション(粘液溶解)、N-アセチルシステイン10-20 mg/kg PO SID、オメガ3脂肪酸サプリ。【参考文献】Couetil LL et al. ACVIM Consensus Statement: Inflammatory Airway Disease/Equine Asthma. JVIM 2016;30:503-515 / Pirie RS. Recurrent airway obstruction. EVE 2014 / Bullone M & Lavoie JP. Equine asthma. EVJ 2017。",
