        merck_url=_MERCK + "exercise+induced+pulmonary+hemorrhage+horses",
        treatment_protocol="【病態】運動誘発性肺出血(EIPH、Exercise-Induced Pulmonary Hemorrhage)— 激運動時の肺毛細血管破綻による肺胞出血。高速運動中に肺血管圧>100 mmHg・気道陰圧>-40 mmHgの極端な圧勾配で毛細血管壁がストレスfailure(West 1993機序)。Thoroughbredレース馬での発生率75-95%(内視鏡)、明視的鼻出血は0.5-10%のみ(軽症が大多数)。Hinchcliff et al. (2005)連続レース解析:EIPH Grade 2+で勝率有意低下。【診断・グレーディング】(1)運動後内視鏡(運動30-90分後):血液が気管内視認、Grade 0-4(0=出血なし、1=少量・<1/4気管、2=気管内流下が長い血流、3=気管・主気管支内の多量血液、4=気管全周から両側気管支内への大量血液 + 鼻孔から visible)。2回連続レース後内視鏡で判定推奨。(2)BAL細胞診:hemosiderophage(青紫染色・Prussian blue陽性マクロファージ)>20%で陽性、最も感度高く長期暴露評価可。(3)胸部X線:慢性例で背側尾側肺野にinterstitial/caudodorsal pattern(Williams 2013)。(4)血中SAA・CKは非特異的。【治療・予防】(1)フロセミド(Salix、Lasix) 0.5 mg/kg IV、レース4時間前単回投与 — 北米レース規則下で唯一のEIPH予防薬承認、血管外液量減少・肺毛細血管圧低下。Hinchcliff (NEJVM 2009)ランダム化試験で出血重症度有意低下(オッズ比3.1)、勝率も改善。ただし多くの管轄(香港・アイルランド・英国・オーストラリア・日本JRA中央競馬)でレース当日使用禁止 — 代替方針必要。(2)鼻腔テープ(FLAIR strip):内鼻腔抵抗低下で吸気圧上昇を軽減、補助的。(3)コンコードグレープシード抽出物(高容量ビタミンC/E):エビデンス限定的。(4)運動制限:Grade 3-4発症馬は2-4週休養 + 漸進復帰、肺組織治癒待機。(5)慢性管理:低粉塵環境(肺炎症はEIPH進行因子、Williams 2013)、BALによる炎症評価、吸入コルチコステロイド併発炎症治療。【予後】Grade 1-2は多くの馬で競技継続可、Grade 3-4反復は競走能力progressive低下 → 引退または用途変更。鼻出血visibleは予後の警告所見。【参考文献】Hinchcliff KW et al. Efficacy of furosemide for prevention of EIPH. NEJVM 2009 / West JB. Stress failure of pulmonary capillaries. Am J Respir Crit Care Med 1993 / Epp TS et al. Impact of EIPH on race performance. EVJ 2008 / Williams KJ. Pulmonary lesions in horses with EIPH. Vet Pathol 2013。",
        clinical_signs_detail="レース・スピードワーク後の鼻出血(両側性または片側性、漿液血性〜新鮮血、通常少量、運動後10-30分で出現し1-2時間で止血)、運動中の突然のfade・パフォーマンス低下、運動後の咳嗽・過剰嚥下(血液気道刺激)、重症は明視的epistaxis流下。内視鏡で気管内血液、BALでhemosiderophage陽性。体温・呼吸数は運動負荷相応、発熱なし",
        risk_factors="Thoroughbred・Standardbred・Quarter Horseのレース馬(最大運動強度、発生率75-95%)、障害飛越・Polo等の激運動競技馬、高齢化(>5歳で頻度・重症度増加)、環境要因(寒冷・乾燥空気・粉塵吸入)、過去のウイルス性・炎症性肺疾患(下部気道炎症がEIPH promoter)、女性馬で発作パターン異なる報告あり、トレーニング強度・頻度、海抜標高(高地で悪化)",
