        merck_url=_MERCK + "atrial+fibrillation+horses",
        treatment_protocol="【診断】聴診で不規則なリズム、安静時心拍>60 bpmで疑診。心電図(ECG): P波消失・f波・RR間隔不整が確定所見。心エコー：左房径(LA)測定、基礎弁膜疾患(MR/TR)評価、LA:Ao比>2.0で予後不良傾向。運動負荷ECG：最大心拍>220 bpmで除細動リスク増。電解質(K+/Mg2+)、甲状腺機能、心筋トロポニンI測定。【薬物的除細動】キニジン硫酸塩 22 mg/kg経鼻胃管 q2h(最大4-6回または合計88 g/500 kg)。投与前後ECG連続監視必須：QRS>25%延長・持続性上室性頻拍・低血圧(<80 mmHg)・消化管症状(疝痛、下痢)で即中止。副作用頻度：疝痛15%、粘膜うっ血20%、上室性頻拍10%、突然死<1%。前投薬：ジゴキシン 0.0022 mg/kg IV(心室応答制御)。【経静脈電気除細動(TVEC)】キニジン無効例・禁忌例(基礎心疾患合併)の代替。全身麻酔下、カテーテル経由で心房内通電(100-300 J)、成功率>95%、van Loon研究。【心不全合併例】フロセミド 1-4 mg/kg IV/IM q6-12h、エナラプリル 0.5 mg/kg PO SID(エビデンス限定的)、ジゴキシン 0.011 mg/kg PO BID(血中濃度 1-2 ng/mL目標)。【モニタリング】除細動後3-6ヶ月ECG再検、LA径フォロー、再発率20-30%/年。【予後】孤発性AF(基礎心疾患なし、LA<130 mm)は除細動率>90%、競走復帰可。基礎心疾患合併は予後不良。【参考文献】Reef VB et al. ACVIM Consensus Statement JVIM 2014; van Loon G et al. Equine Vet J 2010-2020 (Ghent AF series); Marr CM \"Cardiology of the Horse\" 2nd ed; Reed Bayly Sellon \"Equine Internal Medicine\" 4th ed Ch.10.",
        clinical_signs_detail="不規則な心リズム(聴診・触診で検出)、運動時パフォーマンス低下(競走馬で顕著)、運動不耐性、安静時は無症状のことが多い、稀にめまい・虚脱、基礎心疾患合併例では呼吸促迫・頸静脈拍動・末梢浮腫",
