        treatment_protocol="【病態】自律神経節(腸管神経叢・交感神経節)の変性。Clostridium botulinum type C毒素関与説有力(Newton JR et al. EVJ 2004)。英国・スコットランド・北欧で春季多発(4-7月放牧馬)。【形態分類】急性型(生存<48時間、致死率100%)、亜急性型(48時間-7日、致死率100%近い)、慢性型(>7日、唯一生存可能性あり、20-50%)。【診断】臨床症状+疫学+低用量エドロホニウム試験(重度重症筋無力症と鑑別)、Webb涙腺分泌試験(局所バチカン浸透フェニレフリン点眼での瞳孔反応欠如がサポート的)。確定診断は回腸全層生検(神経節細胞のクロマトリシス・消失)または死後病理。【急性型治療(無益、安楽死推奨)】重度胃拡張・頻脈(>80)・乾燥鼻液・嚥下不能・重度発汗は急性型で救命不可。【慢性型の積極的内科治療(院内集中治療必須)】経鼻胃管での胃減圧 q2-4h、シサプリド 0.5-1 mg/kg PO q8h(消化管運動促進、現在入手困難)、メトクロプラミド 0.04 mg/kg/hr CRI、ベサネコール 0.025-0.03 mg/kg SC q4h(ムスカリンアゴニスト、唾液分泌改善)。【栄養管理(重要)】嚥下可能なら高エネルギー粥状流動食(ミルクシェイク状、少量頻回、1日5-8回)を手で食べさせる、食欲刺激(刈りたて牧草、リンゴソース)、経鼻胃管栄養または全胃腸外栄養(TPN、1-2週間)。【輸液・電解質】乳酸リンゲル液 2-4 mL/kg/hr、低カリウム血症・脱水補正。【鎮痛】ブトルファノール 0.01-0.02 mg/kg IV q4h。NSAIDsは腎障害・粘膜障害で慎重。【予後判定基準(Milne et al. EVJ 2010)】24時間以内に経鼻胃管からの流出 <2L、食欲部分回復、排便継続、心拍<60で内科療法継続価値あり。【予防】牧草変更のストレス回避、BoNT/C毒素ワクチン治験中(英国)。参考:Newton JR, Hedderson EJ. Equine grass sickness. EVE 2004;16:77;McGorum BC, Pirie RS. EVJ 2019。",
        clinical_signs_detail="急性型:重度疝痛、大量胃拡張(経鼻胃管で>10 L緑色液体)、持続性頻脈(>80/min)、乾燥・粘稠な鼻涙分泌、嚥下不能、発汗(パッチワーク性)、筋振戦、瞼瞼下垂、食道蠕動欠如。慢性型:重度体重減少(急速な“skeletal”体型)、筋振戦、立ち眠状態(elephant-on-a-tub posture)、鼻涙欠如、軟弱便→重度便秘、嚥下障害、眼瞼下垂、糞粒が砲弾状に乾燥",
        risk_factors="英国・北欧・北海沿岸地域放牧馬(地域素因強い)、2-7歳青壮年馬、春季(4-7月、特に5月)、牧草地変更後7-14日、生物学的最近新入(新規牧草アクセス)、天気変化(寒冷乾燥後の温暖化)、土壌擾乱(放牧地工事)、Clostridium botulinum type C毒素暴露説、大群飼育、高タンパク若草大量摂取",
