        clinical_signs_detail="慢性的・反復性の軽度疝痛、排便量減少または停止、排便時努責、腹部膨満(部分閉塞)、完全閉塞では頻脈・発汗・急性疝痛、小結腸閉塞では直腸検査で腫瘤触知、二次性胃逆流は末期所見",
