    Disease(
        "cv_aortoiliac",
        "大動脈腸骨動脈血栓症",
        "Aorto-Iliac Thrombosis",
        "cardiovascular",
        "severe",
        "Strongylus vulgaris幼虫等による大動脈・腸骨動脈の血栓。後肢跛行・運動不耐性。",
        ["limb_lameness_hind", "cardio_exercise_intolerance", "gen_sweating", "cardio_poor_perfusion"],
        urgency="urgent",
        recommended_exams=[(1, "経直腸超音波", "Transrectal Ultrasound"), (2, "血管造影", "Angiography")],
        merck_url=_MERCK + "aortoiliac+thrombosis+horses",
        treatment_protocol="【診断】経直腸超音波：大動脈三叉部(aortic quadrification)・内腸骨動脈・外腸骨動脈の血栓(低エコー/混合エコー腫瘤)、血流欠損の検出。ドプラ血流評価で患側の血流減少。血管造影(診断ゴールド標準、麻酔下)。運動負荷試験：運動後の後肢触診で患肢温度低下・筋硬直・サドル領域発汗欠如が特徴。血液：CBC、凝固パラメータ(FDP・D-dimer)、Strongylus vulgaris血清抗体・糞便検査。【病因治療】寄生虫性(Strongylus vulgaris幼虫移行の古典的原因、現在減少)：イベルメクチン 0.2 mg/kg PO(幼虫駆虫)、またはモキシデクチン 0.4 mg/kg PO。血栓性・感染性は血液培養で確認。【抗血栓療法】ヘパリンナトリウム 40-100 IU/kg SC q8-12h(初期)、低分子量ヘパリン(エノキサパリン) 40-80 IU/kg SC SID(より均一な効果)。アスピリン 20 mg/kg PO q48h(長期血小板凝集抑制)。ペントキシフィリン 10 mg/kg PO q8h(血液粘稠度低下・側副血行促進)。ワーファリン 0.018-0.075 mg/kg PO SID(PT目標1.5-2倍、凝固モニタリング必須、出血合併症注意)。【血栓溶解療法】tPA(組織プラスミノーゲン活性化因子) 1-2 mg/kg IV 30分かけて注入、急性期のみ有効、高価・出血リスク。【支持療法】疼痛管理にフルニキシンメグルミン 1.1 mg/kg IV q12-24h。運動は慎重に再開(軽度ウォーキング→徐々に増加)。DMSO 1 g/kg IV 10%溶液で血流改善効果報告。【モニタリング】経直腸超音波で血栓サイズ・血流、運動負荷反応、凝固パラメータ、PCV・TP。【予後】慢性例は不良から中等度(競走復帰困難、軽度運動は可)、急性大血栓は予後不良。寄生虫予防改善で近年発生減少。【参考文献】Maxie MG \"Jubb Kennedy Palmer's Pathology\" 6th ed; White NA et al. AAEP Proceedings 1989; Ross MW JAVMA 1988; Marr CM \"Cardiology of the Horse\" 2nd ed; Azevedo JL Equine Vet Educ 2016.",
        clinical_signs_detail="運動後の進行性後肢跛行・筋硬直(競走馬で運動開始5-10分後に出現)、軽度症例では軽微な運動不耐性のみ、患肢の温度低下・弱脈(大腿動脈)、運動誘発性発汗パターン異常(サドル部位発汗欠如)、重症例では運動後に虚脱・横臥、慢性例では筋萎縮(後躯)",
        risk_factors="Strongylus vulgaris幼虫移行(駆虫不十分、放牧管理不良)、高齢馬、長期馬房安静・カテーテル関連血栓、凝固異常・DIC合併症、感染性血管炎、加齢性血管退行変化、サラブレッド競走馬",
    ),
