        urgency="emergency",
        recommended_exams=[(1, "遺伝子検査", "Genetic Testing"), (2, "腹部X線", "Abdominal Radiographs")],
        merck_url=_MERCK + "lethal+white+overo+syndrome",
        treatment_protocol="【疾患概要】Lethal White Overo Syndrome(LWOS / Overo Lethal White Syndrome: OLWS)はEDNRB(エンドセリン受容体B)遺伝子のミスセンス変異(c.353T>A、p.Ile118Lys)による常染色体劣性遺伝性疾患。神経堤由来のメラノサイトと腸管神経節細胞の遊走・分化障害→全身白色被毛+先天性回腸結腸無神経節症(aganglionosis)。蠕動運動完全欠如により出生後12-72時間以内に重度疝痛・胎便排泄不能・腸管壊死で100%致死。【遺伝学的背景】American Paint Horse(Frame Overo pattern)保因率約94%(homozygote=lethal)、Quarter Horse保因率約2.7%、Pinto/Cropout系で発生。常染色体劣性、Frame Overo×Frame Overo交配で25%罹患。Sabino・Tobiano・Splashed Whiteとは別変異。【臨床診断】(1)肉眼所見：全身ほぼ完全白色被毛(時に背線・耳基部・頸部に小斑点)、青色虹彩・薄ピンク鼻(色素欠如)、外見正常で活発に出生。(2)出生後経過：12-24時間以内に進行性疝痛(腹臥位・転がり・後肢蹴り)・胎便排泄なし・腹部膨満・嘔吐様逆流・X線で多発ガス充満腸管・無排便。(3)PCR遺伝子検査(EDNRB Ile118Lys)：UC Davis VGL・APHA推奨検査機関で頬粘膜スワブ・末梢血EDTAから48-72時間で結果、確定診断必須。(4)直腸組織生検(全層厚)：マイエンテリック神経叢神経節細胞欠如(無神経節症)、確定診断、安楽死前または剖検で実施。(5)鑑別診断：胎便停滞(meconium impaction、enema反応する)、結腸不発達(microcolon、稀)、麻痺性イレウス、腸捻転。【治療】(1)根治治療なし、外科切除も不能(無神経節症が広範)。(2)診断確定までの一時緩和ケア：泡石鹸enema(20-30 mL warm soapy water)無効、IV輸液(乳酸リンゲル 4-6 mL/kg/hr)、疼痛緩和(ブトルファノール 0.02 mg/kg IV q4h、フルニキシン 0.5 mg/kg IV q12h、強い疝痛にデトミジン 0.01-0.02 mg/kg IV)。(3)経鼻胃管で逆流貯留液除去(腹圧軽減)。(4)PCR結果(48-72h)入手後、安楽死方針確定。【倫理的判断】予後絶対不良(72時間以内100%死亡)、強烈な疝痛・腸壊死による苦痛から、Frame Overo×Frame Overo間の全身白色子馬は出生時にPCR検査即時依頼、結果判明前でも疝痛・腹部膨満発症時(通常12-24h)に動物福祉観点から早期安楽死(ペントバルビタール 80-100 mg/kg IV)を強く推奨(AAEP・APHA動物福祉ガイドライン)。所有者には事前に遺伝カウンセリング・予後説明必須。【予防(繁殖管理)】(1)American Paint Horse・Pinto・Quarter Horse(Cropout)全繁殖個体のEDNRB PCR検査(APHA推奨、2010年以降)。(2)Frame Overo(N/O)×Frame Overo(N/O)交配絶対回避→Frame×Solid(N/N)またはFrame×Tobiano(別変異)に切替。(3)Sabino・Splashed Whiteなど他白色パターンとの鑑別重要(非致死)。(4)種牡馬広告・繁殖契約に遺伝子型表示推奨。【参考文献】Yang et al. Hum Mol Genet 1998；Metallinos et al. Mamm Genome 1998；Santschi et al. Mamm Genome 1998(EDNRB変異発見)；McCabe et al. Am J Med Genet 1990(初期記載)；Equine Neonatal Medicine (Knottenbelt 2004) Ch.13；APHA OLWS Genetic Testing Guidelines。",
        clinical_signs_detail="(1)出生時：全身完全白色被毛(まれに耳・背線に小有色斑)、青色虹彩(blue eyes)、薄ピンク色鼻部・粘膜(色素欠如)、外見上は活発で起立・哺乳良好、(2)生後12-24時間：胎便排泄なし(meconium非排泄)、進行性腹部膨満(無蠕動でガス・液体貯留)、(3)24-48時間：強烈な疝痛(横臥・転がり・後肢蹴り・歯軋り)、頻脈(>100/min)、頻呼吸、脱水、嘔吐様鼻腔逆流、(4)48-72時間：腸管壊死・敗血症性ショック・低体温・虚脱・死亡。腹部X線で結腸ガス充満・無排便確認",
        risk_factors="【遺伝】Frame Overo色素パターン両親(EDNRB Ile118Lys変異、heterozygote N/O)、両親ともFrame OveroでF×F交配時25%が罹患(Lethal White)。【品種】American Paint Horse(Frame Overo line)、Pinto、Quarter Horse(Cropout)、Spanish Mustang、Miniature Horse、まれにThoroughbred系Cropout。【血統】Mitchell Frame Overo line、Rebel Cause line等。【他白色パターン】Sabino(SB1)・Tobiano(KIT)・Splashed White(MITF/PAX3)は別変異で非致死、Frame Overoのみ致死。【見た目だけでは判別不能】"
