        treatment_protocol="感染動物の隔離・検疫。培養感受性試験に基づく抗菌薬療法：ペニシリン、ゲンタマイシン、ST合剤、エンロフロキサシン。抗真菌療法：全身性アゾール系薬またはアムホテリシンBを真菌感染に使用。支持療法：輸液療法、栄養補助、解熱管理(フルニキシン 1.1 mg/kg IV)。適応時の曝露後ワクチン接種(破傷風、腺疫)。環境消毒、媒介動物対策。届出義務のある疾病は当局に報告。",
