        treatment_protocol="【診断基準】胃内視鏡で幽門洞・胃体部を詳細観察。EGGDはECEIMグレード化せず記述的評価(解剖学的部位・分布・外観：発赤、線状、浸食、潰瘍、線維素付着、出血)。幽門部は操作困難で見落とし多い(Sykes et al. JVIM 2015)。【第一選択(ECEIM推奨)】オメプラゾール 4 mg/kg PO SID + スクラルファート 12 mg/kg PO BID-TID の併用 × 最低8週間(EGGDはESGDより治癒に長期間要する)。空腹時投与が望ましい。スクラルファート単独も粘膜保護作用で有効との報告(Hepburn EVJ 2014)。【難治例】ミソプロストール 5 μg/kg PO BID-TID × 8週間(PGE1アナログ、粘液重炭酸分泌促進、妊娠馬禁忌)。オメプラゾール+ミソプロストール併用が単独より優る可能性(Varley et al. EVE 2019)。【注射用オメプラゾール】長時間型オメプラゾール4 mg/kg IM q5-7日(欧州で販売、経口不可例に有効、Sykes et al. EVJ 2017)。【飼養管理】24時間牧草、ストレス軽減(運動週1日完全休養、安定した厩舎環境)、穀類制限。ESGDほど食事管理への反応が強くないが基盤として重要。【NSAIDs】原則中止。継続必要ならCOX-2選択的(フィロコキシブ 0.1 mg/kg PO SID)へ変更+胃粘膜保護併用。【治癒確認】8週後再内視鏡、未治癒は追加8週間。完全治癒まで4-6ヶ月要する例もある。【拘縮性病変・流出障害】長期病変では幽門狭窄のリスク、内科療法抵抗性なら幽門形成術を検討。【維持療法】治癒後もスクラルファート 12 mg/kg PO SID or BID で再発予防、オメプラゾール維持は個別判断。",
        clinical_signs_detail="慢性疝痛(特に食後)、食欲低下(特に穀類回避)、体重減少、被毛粗剛、性格変化(攻撃性・敏感性増加)、運動能力低下、歯ぎしり、フレーメン反応、鞍傷敏感。ESGDと類似だが治療反応が悪く慢性化しやすい。内視鏡で幽門洞・胃体部に発赤・線状潰瘍・線維素付着を認める",
        risk_factors="運動ストレス(週5日以上の運動)、社会的ストレス(頻繁な馬の入れ替え・競技会)、NSAIDs使用(特にフェニルブタゾン長期)、Warmblood・Thoroughbred品種素因(Warmbloodで有病率高)、性格(神経質な馬)、運動後の冷水給水(可能性)、感染(Helicobacter spp.関与の可能性、未確定)",
