        treatment_protocol="【極めて緊急(診断から手術開始まで<2時間が生存率を左右)】大結腸捻転は馬消化器外科で最も致命的病態の一つ(致死率30-70%、Hackett et al. EVJ 2006)。【診断】突発性の激烈疝痛(薬剤反応不良)、腹部急速膨満(特に左下腹部)、直腸検査で拡張・ガス充満結腸ループ・骨盤曲の異常位置、腹部超音波で結腸壁肥厚(>6mm、虚血徴候)、腹水は初期正常→進行で漿液性→血性、乳酸>4 mmol/L(虚血マーカー、Johnston EVJ 2007)。【術前安定化(手術準備と並行)】高張食塩水7.2% 4 mL/kg IV 急速(10-15分)、LRS 20-30 mL/kg/hr大量輸液、14G×2本頸静脈カテーテル確保、フルニキシン 1.1 mg/kg IV(術前1回のみ、抗エンドトキシン)、ペニシリン 22,000 U/kg IV + ゲンタマイシン 6.6 mg/kg IV、経鼻胃管挿入(胃減圧、通常反流少量)。【外科(ventral midline開腹、必須)】結腸を体外に出し、捻転方向確認(360°が最多、一部で540-720°)、捻転解除、結腸内容物の排除(体外結腸切開 pelvic flexure enterotomy)、虚血評価(漿膜色・蠕動・動脈拍動)。虚血性壊死範囲 >50%で大結腸部分切除術(resection)適応(術後生存率低下)。20-30%の症例で再発リスクあり結腸固定術(colopexy)を検討(Trostle et al. EVJ 1998)。【術後集中治療】リドカインCRI 1.3 mg/kg bolus + 0.05 mg/kg/min(抗炎症+プロキネティック、Malone AJVR 2006)、リポポリサッカライド対策ポリミキシンB 6,000 U/kg IV q8h、蹄葉炎予防(両前肢72時間氷水浸漬、Van Eps AJVR 2009)、凝固モニタリング(DIC警戒)、段階的再給餌(24-48時間)。【予後因子】術前乳酸>6 mmol/L、PCV>55%、捻転>360°、結腸切除>50%で生存率<50%。早期手術・軽度捻転例は60-80%生存。参考:Hackett ES et al. EVJ 2006;38:322;Embertson RM. Large colon volvulus. In Auer & Stick Equine Surgery 5th ed 2018。",
