        recommended_exams=[(1, "内視鏡", "Endoscopy"), (2, "X線", "Radiographs")],
        merck_url=_MERCK + "guttural+pouch+tympany+horses",
        treatment_protocol="【病態】喉嚢鼓脹(Guttural Pouch Tympany、GPT)— 子馬・幼馬の先天性疾患。喉嚢咽頭openingの粘膜弁(plica salpingopharyngea)が一方向弁状に機能不全 → 嚥下時の空気が嚢内へ流入するが排出できず、嚢が空気で異常拡張。Tetens et al. (EVJ 1994)、McCue et al. (Vet Surg 1995)報告。生後数週〜6ヶ月で発症、Arabian・Quarter Horse子馬に多発、雌>>雄(2-4倍)、常染色体劣性遺伝示唆(Metzger et al. 2012)。両側性30-50%、片側性で対側嚢が二次的に膨張することあり。【診断】(1)頸部視診・触診:Viborg's三角(下顎角後方)〜耳下部の非疼痛性弾性腫脹(片側 or 両側)、押すと萎縮するが嚥下後再膨張、(2)頭部・頸部側面X線(ゴールドスタンダード):嚢内空気拡張像、対側嚢の二次膨張評価、Stylohyoid bone正常、(3)喉嚢内視鏡:嚢開口部の機能異常(粘膜弁の浮腫・形態異常)、内腔に膿汁・炎症なし(単純鼓脹)、(4)CT(複雑例):両側性 or 一方の二次膨張区別、外科計画、(5)新生仔の哺乳困難・stridorの鑑別:口蓋裂・後鼻孔閉鎖・気管低形成除外。【治療】(1)外科治療(根治):pharyngeal opening拡大術または fistula creation。手術選択:(a)単側性 → 健側 fenestration(ipsilateral fenestration of medial wall):罹患嚢と健側嚢の中隔に窓を作成、空気を健側嚢経由で排出、Tetens 1994で良好成績。(b)両側性 → salpingopharyngeal fistula creation:両嚢開口部を咽頭腔に永久接続、内視鏡下レーザー(diode/Nd:YAG)で実施可能、立位鎮静下、低侵襲、Texsen 2014で90%奏効。(c)古典的開放手術 → Whitehouse・modified Whitehouse approach:外側からの嚢開窓、現在は内視鏡下が第一選択。(2)術後管理:抗菌薬(セフチオフル 4.4 mg/kg IM q12h × 5-7日)、フルニキシン 0.5 mg/kg IV q12h × 3日、軟食2週、4週で漸進的活動再開、3ヶ月後に再X線で機能確認。(3)二次感染合併(empyema化):rp_guttural_pouch_empyemaプロトコル参照。(4)非手術選択(極軽度):成長期に自然軽快を待機(<10%)、頻回マッサージで嚢空気排出補助 — 但し外科治療なしでは予後限定。【予後】単純GPT手術後:90%以上根治、再発<5%、長期予後良好。複雑性(両側性・empyema合併・誤嚥性肺炎):手術後70-80%治癒、慢性嚥下障害残存リスク。早期外科介入(発症後3ヶ月以内)で機能完全回復。【参考文献】Tetens J et al. Surgical management of guttural pouch tympany. EVJ 1994 / McCue PM et al. Pharyngeal fistulation for tympany. Vet Surg 1995 / Metzger J et al. Genetic analysis of guttural pouch tympany in Arabian foals. Equine Vet J 2012 / Texsen J et al. Endoscopic laser fenestration of guttural pouch tympany. EVJ 2014。",
        clinical_signs_detail="生後数週〜6ヶ月の子馬の頸部背側非疼痛性弾性腫脹(Viborg's三角〜耳下部)、片側性70%/両側性30%、嚥下時stridor、呼吸困難(中等度〜重度)、哺乳・摂食困難、咳嗽、嚥下時の異常な空気音、頭部位置による腫脹変化(立位で増大)。重症例で誤嚥性肺炎合併(発熱・湿性咳嗽)、体重不増加、発育遅延。腫脹押圧で空気漏出音、嚥下後再膨張",
        risk_factors="Arabian子馬(発生率最高)、Quarter Horse・Paint Horse子馬、Warmbloodの一部、雌>>雄(2-4倍、性連鎖示唆)、常染色体劣性遺伝(Metzger 2012、Arabianで遺伝子座同定)、生後3週〜6ヶ月発症、家族集積性(同腹子・同系交配)、片側性〜両側性、母体妊娠中の特定要因不明、地理的偏りなし(品種依存)",
