        risk_factors="初乳の不十分な摂取(IgG移行不全)、不衛生な分娩環境、臍帯感染、免疫不全",
        clinical_signs_detail="出生後48時間以内に元気消失、吸乳力低下、高熱または低体温、関節腫脹、下痢、急速な全身状態悪化",
        general_management="血液培養と広域スペクトラム抗菌薬の静脈内投与。IgG測定と必要に応じた血漿輸血。ICU管理が理想的",
        prognosis="早期発見・治療で生存率50-70%。多臓器不全に進展した場合は予後不良",
        prevention="清潔な分娩環境、出生6時間以内の十分な初乳摂取(IgG>800mg/dL目標)、臍帯の消毒処理",
        treatment_protocol="【疾患概要】Neonatal Septicemia(新生子敗血症)は生後72時間以内発症の全身性細菌感染症で、馬新生子の死亡原因第1位(NICU入院子馬の30-50%、生存率約75%)。FPTを背景とした血流感染→SIRS→多臓器不全へ進行。【病原体】グラム陰性菌(E. coli 30-40%、Klebsiella、Enterobacter、Salmonella、Pseudomonas、Actinobacillus equuli)、グラム陽性菌(Streptococcus、Staphylococcus、Enterococcus)、混合感染多い。【診断(Sepsis Score)】(1)Brewer & Koterba sepsis score(>11=敗血症95%感度):IgG・WBC・好中球未熟核比・血糖・線維素原・PCV・体温・年齢パラメータ複合評価。(2)病歴：FPT既往、不衛生分娩、母馬胎盤異常、難産。(3)臨床所見：発熱(>39°C)/低体温(<37°C)、頻脈(>120/min)、頻呼吸(>40/min)、CRT延長(>3秒)、嗜眠、哺乳意欲喪失、低体温・点状出血(進行例)、関節腫脹、下痢、肺炎、髄膜炎徴候。(4)CBC：白血球増多/減少、好中球未熟核左方移動、トキシック顆粒、フィブリノーゲン>500 mg/dL、SAA>1,000 μg/mL、血小板減少(DIC)、PCV正常〜高値(脱水)。(5)血液培養(必須・複数本)：好気・嫌気・血液入りボトル、抗菌薬投与前に2-3部位から採血、48-72hで結果。陽性率30-60%(抗菌薬前投与で低下)。(6)IgG測定：<400で完全FPT、400-800で部分FPT、敗血症の80%以上にFPT併発。(7)血液生化学：低血糖(<60 mg/dL)、乳酸>4 mmol/L、AST/CK上昇、ビリルビン上昇、BUN/Cr上昇、低Na/K血症、肝酵素上昇。(8)血液ガス：代謝性アシドーシス、低酸素血症。(9)感染源検索：腹部超音波(臍動脈・尿膜管・肝)、胸部X線(肺炎)、関節穿刺(腫脹関節)、CSF穿刺(神経症状時)、創傷検査。【緊急治療(初期24時間)】(1)血管確保(頸静脈14-18Gカテーテル)、輸液：晶質液(乳酸リンゲル液) 4-6 mL/kg/hr 持続、ショック時20 mL/kgボーラス×3まで(過剰輸液回避)、デキストロース2.5-5%併用(低血糖維持)、コロイド(VetStarch 5-10 mL/kg)。(2)抗菌薬(培養結果待たず即時開始、変更は感受性結果後):第一選択 ペニシリンG 22,000-44,000 U/kg IV q6h+アミカシン 25 mg/kg IV SID(腎機能要監視、血中濃度モニタリング)、または セフチオフル 5 mg/kg IV q12h(NICU第一選択、24h以内に全身分布)、重症例は セフタジジム 5 mg/kg IV q8h+アミカシン、グラム陽性疑いはセファゾリン10 mg/kg IV q8h、メトロニダゾール15 mg/kg PO/PR q8h(嫌気性疑い)、最低7-14日IV。(3)血漿輸血(必須):ハイパーイミューンプラズマ 20-40 mL/kg IV(IgG<400で40 mL/kg、400-800で20 mL/kg)、緩徐(最初20分は0.1-0.2 mL/kg/min、輸血反応観察)、6-12h後IgG再検→<800なら追加。(4)昇圧薬(MAP<60 mmHg持続)：ドブタミン 5-10 μg/kg/min IV CRI(循環支持)、ノルエピネフリン 0.1-1 μg/kg/min IV CRI(難治性低血圧)、バソプレシン 0.25-0.5 mU/kg/min(カテコラミン抵抗性)。(5)グルコース：5%デキストロース併用 2-4 mg/kg/min、血糖80-150 mg/dL維持(>200は持続)、血糖q2-4h監視。(6)栄養：哺乳意欲ある→母乳継続、ない→経鼻胃管 母乳/代用乳 100-150 mL/kg/日(2-4h毎少量)、絶食必要時はTPN(30-40 kcal/kg/日)。【支持療法】(7)抗潰瘍：オメプラゾール 4 mg/kg PO SID または スクラルファート 1-2g PO QID。(8)疼痛管理：ブトルファノール 0.02-0.04 mg/kg IV q4-6h、フルニキシン 0.5-1.1 mg/kg IV q12h(腎機能・脱水補正後、最大3-5日)。(9)抗血栓：ヘパリン40-80 U/kg SC q8h(DIC合併時、調整困難)、新鮮凍結血漿(凝固因子補充)。(10)感染源管理：化膿性関節炎は関節洗浄+RLP、臍動脈感染は超音波下抜去、肺炎は気管洗浄培養。(11)モニタリング：体温q4h、心拍・呼吸数q2-4h、血糖q4-6h、乳酸・血液ガスq6-12h、IgG q12-24h、CBC・SAA q24h、尿量・体重(輸液過剰防止)、神経症状連続評価。【予後】Brewer/Koterba scoreで層別化：軽症(<8)生存率90%、中等症(8-11)70-80%、重症(>11)40-60%。早期介入(発症12h以内)・適切な抗菌薬・FPT補正で予後改善。後遺症：化膿性関節炎による跛行(20-30%)、髄膜炎後神経症状(5-10%)、成長遅延(慢性例)。【予防】出生6h以内初乳1L摂取確認、12hでIgG測定→<800で血漿輸血、清潔分娩環境(消毒済stall・清潔敷藁)、臍帯処理(2%クロルヘキシジン浸漬 q4-6h × 24-48h、ヨードチンキは強すぎる)、母馬胎盤炎の早期治療(ヒドロキシ尿素・トリメトプリム-スルファ)、母馬ワクチン(ロタウイルス、E. coli)、子馬温度・血糖維持。【参考文献】Brewer & Koterba J Vet Intern Med 1988(sepsis score)；Hollis et al. JVIM 2008(治療)；Sanchez & Giguere AAEP Proc 2002；Wong & Wilkins Vet Clin Equine 2015；Equine Neonatal Medicine (Knottenbelt 2004) Ch.18；Robinson/Sprayberry Current Therapy 7th ed Ch.156。",
