        merck_url=_MERCK + "hemothorax+horses",
        treatment_protocol="【病態】馬の血胸(Hemothorax)— 胸腔内出血貯留 → 肺虚脱 + 失血性ショック+呼吸不全。Mair (EVJ 1991)、Perkins et al. (JVIM 2007)。原因:外傷性(肋骨骨折、刺創、銃創、胸部打撲)、医原性(胸腔穿刺中の肋間動脈損傷、胸部手術合併症)、新生物性(肺・胸膜新生物 — 血管肉腫・原発性肺腫瘍)、凝固障害(DIC・ワルファリン中毒・血小板減少症)、肺血管疾患(動脈瘤・血管炎)、guttural pouch mycosisからの大動脈系出血(rare、咽頭から下行)。緊張性血胸は致死的失血 + 呼吸不全併発、即時対応必須。【診断・救命処置(emergency)】(1)胸部超音波(ゴールドスタンダード):特徴的所見 — 胸腔内液体貯留(無エコー〜微細点状エコー、新鮮血)、肺虚脱(consolidation様)、胸水中の渦流動(swirling)で活動性出血示唆、両側必須スキャン、(2)胸部X線(超音波後の補助):両側性または片側性陰影、横隔膜消失、心臓位置、(3)即時診断的thoracocentesis(超音波ガイド下):14-16 G 8-12 cm カテーテル、7-9th intercostal space ventral 1/3、無菌的、サンプル分析(HCT 比較で血液確認 — 血胸 ≒ 静脈血HCT、漿液性胸水との鑑別)、培養 + 細胞診(感染合併・新生物細胞検索)、(4)CBC + 凝固時間(PT/PTT、フィブリノゲン、血小板数):失血量評価、凝固障害除外、(5)Type and crossmatch(輸血準備):新鮮全血 or 濃厚赤血球、(6)動脈血ガス:重度低酸素血症、代謝性アシドーシス、乳酸 >3、(7)出血源評価(安定後):CT、内視鏡(guttural pouch mycosis除外)、心エコー(心血管原因)、新生物精査、(8)外傷既往詳細聴取。【救命的治療】(1)即時IV輸液(失血性ショック対策):乳酸リンゲル液 20-40 mL/kg ボーラス IV、目標 — MAP>70 mmHg、CRT<3秒、HR<80、HCTモニタリング(過剰輸液で稀釈性貧血悪化)、(2)新鮮全血または濃厚赤血球輸血(失血量>20%・HCT<20%):馬血液型確認(jugular veinから10-15 L/300 kg、Aa・Qa-negative donor、cross-match推奨)、輸血関連肺障害(TRALI)・反応性高熱・urticariaに注意、ジフェンヒドラミン 0.5-1 mg/kg IV slow 前投与、(3)アミノカプロン酸 25-40 mg/kg IV slow q6h(線溶抑制、エビデンス限定)、トラネキサム酸 5-10 mg/kg IV q8h、(4)凝固障害対応:新鮮凍結血漿 6-10 mL/kg IV(凝固因子補充)、ビタミンK1 0.5-1 mg/kg IM q24h × 3日(ワルファリン中毒・肝不全)、血小板輸血(<50,000で活動性出血)、(5)thoracocentesis(治療的、適応慎重):大量胸水で重度呼吸困難 → 部分排液で呼吸機能改善(過剰排液は再出血誘発)、Heimlich弁付きで持続留置はしない(再出血モニタリング困難)、(6)外科的止血(限定):大型出血源(肋間動脈・大型肺血管)・血胸 + 持続性血流出 → thoracotomy + 直接結紮、専門施設で稀に実施、(7)酸素吸入:鼻腔カニューレ 10-15 L/分、SpO2>90%目標、(8)鎮静(必要時、興奮で出血増悪):ブトルファノール 0.01-0.02 mg/kg IV、(9)抗菌薬予防(外傷性・カテーテル留置):セフチオフル 4.4 mg/kg IM q12h × 5-7日、(10)NSAIDsは原則禁忌(出血増悪リスク、重度疼痛時のみ慎重低用量フェニルブタゾン)。【根本原因治療】guttural pouch mycosis → 経動脈コイル塞栓(rp_guttural_pouch_mycosis参照)、新生物 → 化学療法・放射線・緩和ケア、凝固障害 → 原因疾患治療。【予後】単純外傷性 + 早期治療:生存率50-70%、長期は肺機能個別評価。新生物性・大量失血 + ショック:生存率<30%、慢性化・反復出血で予後不良。Guttural pouch mycosis原因 + 早期コイル塞栓:救命率90%。【参考文献】Mair TS et al. Equine pleural disease. EVJ 1991 / Perkins GA et al. Hemothorax in 9 horses. JVIM 2007 / Sweeney CR. Pleural disease in horses. Vet Clin North Am Equine 1991 / Magdesian KG. Transfusion medicine in horses. Vet Clin North Am Equine 2004。",
        clinical_signs_detail="急性発症の重度呼吸困難 + 失血性ショック徴候(粘膜蒼白、CRT延長>3秒、頻脈>80/分、頻呼吸>40/分、低血圧)、両側性または片側性胸部聴診で呼吸音減弱・消失 + 打診でdullness(液体貯留)、外傷例では胸壁皮下血腫・刺傷視認、新生物性では既往の体重減少・腫瘤触知、ガッタラルポーチ起源では鼻出血既往併発、嗜眠〜虚脱(失血進行)、HCT急速低下(<20%)、乳酸上昇(>3)、出血ショックの全身症状",
        risk_factors="胸部外傷(肋骨骨折・転倒・蹴傷・刺創・銃創 — 外傷性が最頻)、医原性(胸腔穿刺中の肋間動脈損傷、胸部手術合併症 — pleuropneumonia治療中要注意)、新生物性(原発性肺腫瘍・血管肉腫・胸膜中皮腫、高齢馬で多い)、凝固障害(DIC・ワルファリン/sweet clover中毒・血小板減少症・血友病類似疾患)、肺血管疾患(動脈瘤・血管炎)、guttural pouch mycosisからの咽頭〜下行性出血、競技馬の外傷リスク高、性別・品種偏りなし",
