        ["resp_unilateral_discharge", "dental_facial_swelling", "resp_nasal_discharge"],
        urgency="routine",
        recommended_exams=[(1, "頭部X線", "Skull Radiography"), (2, "内視鏡検査", "Endoscopy"), (3, "CT検査", "CT Scan")],
        merck_url=_MERCK + "sinusitis+horses",
        treatment_protocol="【病態】馬の原発性副鼻腔炎(Primary Sinusitis)— 上気道感染後の合併症として、または細菌・真菌の一次性副鼻腔感染で発症する idiopathic ・post-viral 形態。Dixon et al. (EVE 2012)分類で全副鼻腔炎の30-40%。続発性副鼻腔炎(歯原性、嚢胞、新生物等)を除外して診断。代表的原因菌:Streptococcus equi subsp. zooepidemicus(>40%)、Pasteurella、Actinobacillus、Staphylococcus、嫌気性菌(Bacteroides、Fusobacterium)、慢性化での真菌(Aspergillus、Cryptococcus)。【診断】(1)頭部側面・正面X線(必須):副鼻腔の液体水準(fluid line)、明確な歯根尖周囲透過性陰影なし(続発性鑑別)、(2)頭部CT(歯原性除外に必須、Tucker EVE 2016で診断精度95%):上顎臼歯歯根の状態評価、副鼻腔解剖の精密確認、嚢胞・新生物・血腫の除外、(3)上気道〜鼻腔内視鏡:nasomaxillary openingからの膿汁流出視認、副鼻腔内空気量推定、(4)trephination + sinus aspirate(治療的診断):無菌的骨穿孔(rostral maxillary trephine)、内視鏡下sinusoscopy + 細胞診 + 培養 + 感受性、(5)歯科精密検査(必須、続発性歯原性除外):上顎臼歯のオーラル・X線評価、咬合面検査。【治療(原発性のため抜歯不要、保存療法主体)】(1)trephination + 副鼻腔洗浄(治療の基盤):無菌的骨穿孔(rostral maxillary 4-5 cm内側、前額洞 4-5 cm dorsal)、Foley balloon カテーテル(20-30 mL)留置、生理食塩水 1-2 L/副鼻腔 q12-24h × 14-21日、温水使用、(2)全身抗菌薬(培養感受性ベース):ペニシリンG 22,000 IU/kg IV q6h × 7-14日 → プロカインペニシリン 22,000 IU/kg IM q12h × 14日継続、慢性化はトリメトプリム・スルファメトキサゾール 30 mg/kg PO q12h × 4-6週、エンロフロキサシン 7.5 mg/kg PO q24h × 4週(成馬のみ)、セフチオフル 4.4 mg/kg IM q12h × 14日代替、(3)局所抗菌薬:洗浄液中にゲンタマイシン 100 mg/L、ペニシリン 1MIU/L 添加(エビデンス限定だが慢性例で試用)、(4)NSAIDs:フェニルブタゾン 2.2 mg/kg PO q12h × 7-14日(疼痛・浮腫)、(5)mucolytics(粘液溶解):アセチルシステイン 200-600 mg ネブライゼーション q12h × 2週、(6)栄養支持:咀嚼・嚥下違和感あれば軟食、ウォームメッシュ・ペレット浸水給与。慢性難治・真菌性:(1)真菌性確認 → enilconazole 50 mg/mL 嚢内噴霧 q24h × 14日、ナタマイシン懸濁液局所、全身イトラコナゾール 5 mg/kg PO q24h × 60-90日、(2)肉芽腫切除:内視鏡下forceps debridement、(3)外科ドレナージ拡大:大型 frontonasal bone flap で広範ドレナージ。【予後】早期診断・治療:80-90%治癒。慢性化(>3ヶ月):60-70%治癒、再発率15-20%。真菌性:6-12ヶ月の長期治療必要、治癒率60-80%。【参考文献】Dixon PM et al. Equine paranasal sinus disease: a long-term study of 200 cases. EVJ 2011 / Tremaine WH, Dixon PM. Long-term study of 277 cases of equine sinonasal disease. EVJ 2001 / Tucker R et al. CT findings in equine sinus disease. EVE 2016 / Hawkins JF. Sinus surgery. Equine Surgery (Auer/Stick 5th ed)。",
        clinical_signs_detail="片側性慢性鼻汁(粘液膿性、無臭〜軽度臭、歯原性の腐敗臭は不在 — 重要鑑別点)、片側性顔面腫脹(軽度、歯原性ほど顕著ではない)、軽度発熱(38.5-39°C)、軽度頸部リンパ節腫大、運動不耐性軽度、頭部叩打音で罹患側dull、慢性化で体重減少・全身衰弱、咳嗽・嚥下違和感は軽度。歯科検査・X線で歯根尖周囲膿瘍を除外確認することが診断に必須",
        risk_factors="過去のウイルス性呼吸器感染(equine influenza・EHV-1/4・EVA)既往、S. equi/zooepidemicus上気道感染既往、長期免疫抑制(PPID・ストレス・栄養不良)、若馬〜中年馬(原発性は中年期に多い)、慢性鼻粘膜炎症、密集飼育・劣悪換気、長期厩舎飼養、原発性は歯科疾患・嚢胞合併なしが診断条件、品種・性別偏りなし",
