        merck_url=_MERCK + "dental+sinusitis+horses",
        treatment_protocol="【病態】続発性副鼻腔炎(歯原性、Secondary Sinusitis-Dental Origin)— 上顎臼歯の歯根尖周囲膿瘍 → 副鼻腔床骨破壊 → 副鼻腔への感染拡大。Dixon et al. (EVE 2011)で副鼻腔炎全体の60-70%。代表的歯:第108・208(上顎第二臼歯、根尖が rostral maxillary sinus内)、第109・209(第三臼歯、 rostral/caudal maxillary sinus)、第110・210(第四臼歯、 caudal maxillary sinus)、第111・211(若馬の第一前臼歯、 rostral maxillary sinus)。 中年馬(8-15歳)に好発(歯根の長さ・歯科的不整 + 年齢関連の歯髄壊死)、中老齢馬(>15歳)では歯根萎縮で発生減少。【診断(歯科精密診断が決定的)】(1)詳細な口腔内検査(必須):鏡 + 強光下、歯式番号(Triadan)記録、咬合面検査、歯周ポケット計測(>5 mm異常)、歯動揺、波形破折、隆起、歯髄露出、(2)頭部側面・斜位X線(歯科専用ビュー):対象歯の歯根尖周囲透過性陰影、歯歯周膜拡大、歯髄腔拡大、副鼻腔床透過性病変、(3)頭部CT(ゴールドスタンダード、Tucker EVE 2016):3D歯根状態・副鼻腔骨破壊・膿瘍範囲を精密評価、外科計画必須、(4)上気道〜鼻腔内視鏡:nasomaxillary openingからの腐敗臭膿汁排出、(5)trephination + sinusoscopy + 培養:無菌的副鼻腔骨穿孔、内視鏡下に病変直接観察、(6)歯科probe:歯周ポケット深さ、歯動揺度評価。【治療(罹患歯抜歯が必須・決定的)】(1)罹患歯抜歯 — 治療の根本(これなしでは保存療法不応):手法選択:(a)経口アプローチ(per oral extraction):若い歯・歯動揺著明、立位鎮静下に歯科鉗子で抜去 — 第一選択(低侵襲)、Tremaine 2007で30-60%成功(歯動揺度依存)、(b)経副鼻腔repulsion(古典的):全身麻酔下、副鼻腔骨弁(frontal/maxillary trephination)→ 罹患歯を口腔へ叩出、現在は最終手段(合併症多)、(c)経頬buccotomy approach:中間侵襲、上顎側面から直接アクセス、Sullins/Burba 2012、(d)minimally invasive transbuccal screw extraction(MITSE、Stoll/Kubitz 2018):頬部骨板に小孔を開け、歯歯軸方向にスクリューで抜去、低侵襲・歯科臨床で普及、(2)抜歯後 副鼻腔ドレナージ:trephination + Foley balloon留置 + 生理食塩水洗浄 q12-24h × 14-21日、抜歯穴の歯槽石膏(dental impression material)封鎖、(3)全身抗菌薬:ペニシリンG 22,000 IU/kg IV q6h + メトロニダゾール 25 mg/kg PO q8h(嫌気性必須カバー、口腔細菌混合)× 14-21日、感受性試験で調整、(4)NSAIDs:フルニキシン 1.1 mg/kg IV q12h × 5日 → フェニルブタゾン 2.2 mg/kg PO q12h維持、(5)栄養支持:抜歯後3-7日は軟食(浸水ペレット・溶きフィード)、咬合面の代償治療、(6)歯科継続フォロー:対側歯の過長(代償性弧長)、咬合面異常を防止 q3-6ヶ月。【予後】罹患歯適切抜歯 + 副鼻腔ドレナージ:80-85%治癒(Dixon 2011)、再発率10-15%(残存歯片 or 第二罹患歯発症)。歯科処置不適切・遅延診断:慢性化、副鼻腔骨破壊進行、再発反復、leisure 馬としても困難。【参考文献】Dixon PM et al. Equine paranasal sinus disease: long-term study of 200 cases. EVJ 2011 / Tremaine WH, Dixon PM. Long-term study of 277 cases of equine sinonasal disease. EVJ 2001 / Tucker R et al. CT findings in equine sinus disease. EVE 2016 / Stoll M, Kubitz A. Minimally invasive transbuccal screw extraction. EVE 2018 / Sullins KE, Burba DJ. Dental sinusitis treatment outcomes. AAEP Proc 2012。",
        clinical_signs_detail="片側性慢性鼻汁(粘液膿性、強い腐敗臭が特徴 — 原発性と最重要鑑別点!)、片側性顔面腫脹(罹患歯対応部位、上顎臼歯108-110/208-210相応)、口臭(halitosis)、咀嚼困難・偏咀嚼・落とし食い(quidding)、軽度〜中等度発熱、頸部リンパ節腫大、頭部叩打音で罹患側dull、頬部触診で疼痛、口腔内検査で罹患歯の動揺・破折・歯周ポケット深化(>5 mm)、長期化で体重減少",
        risk_factors="中年馬(8-15歳、好発年齢、歯根活発・副鼻腔接触最大)、上顎臼歯の咬合面異常(over-grown、enamel point、wave/step mouth)、歯科処置頻度低・floating不十分、歯破折(外傷・採食硬物)、過去の歯髄壊死、第108・109・110/208・209・210上顎臼歯(根尖が副鼻腔内)、品種偏りなし、歯科疾患の家族集積はなし(個体歯科ケア依存)",
