        merck_url=_MERCK + "sinus+cyst+horses",
        treatment_protocol="【病態】馬副鼻腔嚢胞 — 重複エントリー、外科的管理・複雑症例の視点。本エントリーは大型・両側性・複雑性嚢胞の手術選択、新生物との鑑別、再発例の管理に焦点。Tremaine et al. (EVJ 2001) 277例long-term study、Lane (EVJ 1987)、Tucker (EVE 2016 CT)。新生物との誤診リスク高(扁平上皮癌・腺癌・鼻腔リンパ腫)、術前確定診断が必須。【新生物との詳細鑑別】(1)CT精密評価(必須):嚢胞=境界明瞭・骨吸収はあるが整然・内容均質、新生物=境界不整・浸潤性骨破壊・不均質造影、(2)MRI(設備あれば):軟組織コントラスト、(3)術前生検(立位鎮静下、内視鏡下forceps or trephine biopsy):組織学的良悪性確定、扁平上皮癌・腺癌・脂肪腫・線維腫・骨化病変等の鑑別、(4)嚢胞液分析:嚢胞=透明〜黄褐色・粘性・cholesterol crystal・好中球少数、新生物=血性・腫瘍細胞、(5)血液検査:新生物転移評価(肝機能・LDH・カルシウム)、PCR(リンパ腫疑い)。【複雑性嚢胞の手術戦略】(1)大型・多房性嚢胞:大型frontonasal bone flap + maxillary bone flap 複合、嚢胞分隔まで完全除去、術中出血制御 + 一時nasal packing、(2)両側性嚢胞(稀):2期手術(片側ずつ、6-8週間隔)、同時手術は出血リスク高、(3)眼球圧迫例:眼科的評価併施、術後視力monitoring、眼球突出は通常術後解除、(4)咽頭狭窄合併:後部嚢胞の咽頭壁圧迫、術後ICS継続で粘膜浮腫管理、(5)上顎洞下壁(歯根接触)嚢胞:歯根損傷リスク、術中歯科精査 + 場合により罹患歯抜歯併施、(6)再発例の手術:癒着・瘢痕で技術的難易度高、CT再評価 + 追加切除範囲決定、Hawkins 2009で2回目手術成功率70%。【術後管理(複雑例特化)】(1)抗菌薬広範:ペニシリンG 22,000 IU/kg IV q6h × 7日 → セフチオフル 4.4 mg/kg IM q12h × 14日、慢性炎症組織あればトリメトプリム・スルファメトキサゾール 30 mg/kg PO q12h × 4週、(2)強力NSAIDs:フルニキシン 1.1 mg/kg IV q12h × 7日、(3)止血管理:術後3-5日厳格nasal packing、出血モニタリング、緊急時は再手術、(4)副鼻腔ドレナージ:Foley balloon留置 q12-24h × 14-21日、生理食塩水 + 局所抗菌薬洗浄、(5)栄養支持:軟食 + 静注栄養補助(食欲低下時)、(6)眼科ケア:術後眼球運動・視力評価、腫脹解消まで人工涙液・抗生眼軟膏、(7)長期フォロー:3-6ヶ月毎CT再評価で再発monitoring、組織学的悪性確診なら別治療プロトコル(化学療法・放射線治療)。【予後】単純大型嚢胞完全切除:80-90%根治、再発10-20%。両側性・歯根関与・新生物確診:予後個別判断、悪性なら6ヶ月-2年の生存期間で安楽死検討、leisure用途の長期維持は可能。【参考文献】Tremaine WH, Dixon PM. Long-term study of 277 cases of equine sinonasal disease. EVJ 2001 / Lane JG et al. Paranasal sinus cysts. EVJ 1987 / Tucker R et al. CT findings in equine sinus disease. EVE 2016 / Hawkins JF. Sinus surgery techniques. Equine Surgery (Auer/Stick 5th ed) / Quinn GC et al. Sinus tumors and cysts: outcomes. EVE 2009。",
        clinical_signs_detail="複雑性副鼻腔嚢胞:大型・進行性顔面腫脹(明瞭な骨性硬度・非対称)、眼球突出または下方変位(眼窩圧迫)、両側性鼻孔気流低下、慢性的嚢胞液性鼻汁(粘性・茶褐色・無臭)、咽頭狭窄症状(stridor・嚥下困難)、慢性疼痛(顔面神経刺激)、長期化で体重減少著明・全身衰弱。新生物との鑑別重要(CT・組織学的精査必須)、術後再発例では既往手術瘢痕・癒着所見",
        risk_factors="大型嚢胞(>5 cm)、両側性、複数副鼻腔関与、上顎洞下壁(歯根接触)病変、過去の手術後再発例、新生物との臨床的鑑別困難例、高齢馬(>15歳)で新生物リスク高、過去の頭部外傷・歯科処置既往、慢性鼻腔疾患、性別偏りなし、品種偏りなし、診断遅延例(年単位の進行)",
