    Disease(
        "fl_neonatal_isoerythrolysis2",
        "新生子溶血性貧血(NI)",
        "Neonatal Isoerythrolysis",
        "foal",
        "critical",
        "母馬の初乳中の抗体による子馬赤血球の溶血。黄疸・貧血。",
        ["foal_jaundice", "foal_lethargy", "gen_pale_mucosa", "gen_tachycardia", "uri_discolored_urine"],
        age_predisposition="young",
        urgency="emergency",
        recommended_exams=[(1, "血液検査(PCV)", "CBC (PCV)"), (2, "血液型判定", "Blood Typing"), (3, "ジャウンディスフォールアガー試験", "Jaundiced Foal Agglutination Test")],
        merck_url=_MERCK + "neonatal+isoerythrolysis+horses",
        treatment_protocol="【焦点：臨床診断・初期評価】(本項はNI診断のJFA試験・血液型判定・初期管理。輸血実施・繁殖予防策の詳細はfl_neonatal_isoerythrolysis参照)。【疾患概要】Neonatal Isoerythrolysis(NI)は母馬がAa・Qa・Db・Ua等の同種血液型抗原に対する抗体を保有(前回妊娠経胎盤・分娩時感作、または以前の輸血感作)、初乳を介して子馬の腸管から抗体が吸収され子馬赤血球と反応→補体介在性溶血を引き起こす疾患。Thoroughbred・Standardbred・Mule(雄ロバ×雌馬)で頻度高く、初乳吸収後12-48時間で急性発症。【臨床診断アプローチ】(1)出生時の確認事項：母馬病歴(経産・前回NI歴・輸血歴)、Thoroughbred/Standardbred/Mule妊娠、初乳吸収開始時間、子馬の活気・哺乳意欲(出生時は正常)。(2)生後12-24時間以降の症状観察：(a)進行性沈鬱・嗜眠、(b)哺乳量減少・哺乳意欲低下、(c)粘膜蒼白(進行性、初期は気付きにくい)、(d)頻脈(>120/min、徐々に上昇)、(e)頻呼吸(>40/min)、(f)虚脱・横臥位(重症)。(3)生後24-48時間の典型症状：(a)黄疸(jaundice、舌・強膜・歯肉・耳介内側の濃黄色着色)、(b)暗赤色〜茶褐色尿(ヘモグロビン尿、特徴的)、(c)毛細管再充満時間延長(>3秒)、(d)体温正常または軽度低下、(e)時に軽度発作・神経症状(高ビリルビン血症性脳症)。【検査診断】(1)CBC(必須・第一線検査):(a)PCV急速低下(健常子馬>30%、軽症25-30%、中等症15-25%、重症<15%)、(b)Hb・RBC count減少、(c)自家凝集像(spontaneous agglutination、スライド標本で確認)、(d)球状赤血球(spherocytes、補体介在性溶血の特徴)、(e)好中球増多(炎症反応)、(f)血小板減少可能性、(g)Coombs(direct)：陽性が多いが時に陰性(感受性限定的)。(2)血液生化学：間接ビリルビン上昇(主に間接型、肝処理能を超える)、AST/LDH軽度上昇(溶血指標)、BUN/Cr上昇(脱水・腎尿細管壊死)、低タンパク血症(慢性化)、電解質正常。(3)尿検査：ヘモグロビン尿(尿試験紙でblood positive、顕微鏡でRBC無し or少)、ビリルビン尿、尿比重正常〜上昇(脱水)。(4)Jaundiced Foal Agglutination test(JFA、必須・ベッドサイド診断):(a)目的：母馬血清(または初乳)中の抗子馬赤血球抗体検出。(b)手技：母馬血清(または初乳1 mL希釈) + 子馬赤血球(EDTA血0.5 mL生食2回洗浄)+ 生理食塩水を試験管系列に倍数希釈(1:2、1:4、1:8、1:16、1:32、1:64...)→室温37°C 15-30分→2,000g 1分遠心→赤血球凝集判定。(c)判定：1:16以上で凝集陽性=NI診断確定、1:8以下=陰性または弱陽性、母馬血清と初乳両方検査推奨(初乳の方が抗体濃度高い)。(d)感度・特異度：80-90%、迅速・経済的・現場可能。(5)交差適合試験(cross-match、輸血ドナー選定用):(a)Major cross-match：母馬血清(または初乳)+ 候補ドナー馬RBC、(b)Minor cross-match：候補ドナー血清 + 母馬RBC、両試験陰性のドナー選定。(6)血液型判定(major reference labs)：Aa・Qa・Db・Ua確認、UC Davis VGLなど専門ラボで実施、ドナー馬と適合確認、48-72時間結果。(7)血液ガス：代謝性アシドーシス(乳酸蓄積、組織低酸素)、低酸素血症(重症貧血)。(8)IgG測定：FPT併発確認(輸血時の感染リスク評価)。【鑑別診断】(1)新生子敗血症(発熱・低体温・IgG低下・PCV正常〜低下・血液培養陽性、JFA陰性)、(2)他原因溶血性貧血(EHV-1感染、赤血球毒物質、自己免疫性溶血)、(3)新生子肝不全(黄疸+肝酵素著明上昇、ビリルビン尿色違い)、(4)Tyzzer病(5-42日齢、肝壊死、急速死)、(5)出血性貧血(臍帯出血・分娩時出血、皮膚紫斑)、(6)失血性ショック、(7)溶血性尿毒素症候群。【急性期管理(輸血前安定化)】(1)初乳摂取即時中止：診断時点で母乳吸啜中止(36-48時間まで母乳禁止)、母馬から搾乳・廃棄(乳房張りで再開可能)、(2)代用乳または陰性ドナー馬初乳/牛初乳で哺乳(50-100 mL/hr経鼻胃管 q1-2h、栄養維持)、(3)輸液(乳酸リンゲル液 4-6 mL/kg/hr、過剰輸液回避)、(4)酸素補給(経鼻カニューレ 5-10 L/min、SpO2<90%で)、(5)抗潰瘍薬(オメプラゾール 4 mg/kg PO SID)、(6)体温維持・保温、(7)輸血適応評価(PCV<15%、虚脱、乳酸>4)→fl_neonatal_isoerythrolysis参照で輸血実施、(8)コルチコステロイド(議論的、デキサメタゾン 0.05-0.1 mg/kg IV q12h × 2-3日、溶血抑制効果可能性、感染リスクと天秤)、(9)抗菌薬予防(セフチオフル 5 mg/kg IV q12h、輸血関連感染予防)、(10)IgG補正(<800で血漿輸血)。【モニタリング】PCV/TP・血糖・乳酸・心拍・呼吸数・体温を6-12時間毎、ビリルビン・Cr q24h、尿色調・尿量、虚脱徴候。【予後】早期診断(JFA陽性確認、輸血開始)で生存率80-90%、PCV<12%・虚脱例50-70%、無治療では致死率60-80%。腎尿細管壊死合併で予後悪化。【参考文献】Becht J Equine Vet Sci 1983(臨床病理); MacLeay J Equine Vet Sci 2001(JFA法); Boyle et al. JVIM 2005; Polkes et al. JVIM 2008(予後); Equine Neonatal Medicine (Knottenbelt 2004) Ch.16; Robinson/Sprayberry Current Therapy 7th ed Ch.156。",
        clinical_signs_detail="(1)出生時は外見正常で活発、起立・哺乳良好、(2)生後12-24時間：進行性沈鬱・嗜眠・哺乳量減少、(3)生後24-48時間：黄疸(舌・強膜・歯肉・耳介の濃黄色着色)、暗赤色〜茶褐色尿(ヘモグロビン尿、特徴的)、(4)粘膜蒼白(初期は気付きにくく進行性)、(5)頻脈(>120/min)・頻呼吸(>40/min)、(6)毛細管再充満時間延長(>3秒)、(7)体温正常または軽度低下、(8)虚脱・横臥(重症例)、(9)時に発作・神経症状(高ビリルビン血症性脳症)、(10)母馬は正常(無症状)、(11)PCV急速低下(<15%重症)、(12)スライド標本で自家凝集像、(13)JFA test 1:16以上陽性",
        risk_factors="【母馬要因】(1)経産母馬(前回妊娠で胎仔赤血球抗原に感作)、(2)前回NI発症母馬(以後の妊娠でリスク高)、(3)母馬輸血歴(他血液型抗原に感作)、(4)Thoroughbred・Standardbred(Aa・Qa血液型不適合多い)、(5)Mule妊娠(雄ロバ×雌馬、Donkey Factor抗原で約10%発症リスク)、(6)母馬同種輸血経験(同一血液型確認失敗)。【血液型不適合】(1)Aa血液型：父Aa(+)/母Aa(-)、(2)Qa血液型：父Qa(+)/母Qa(-)、(3)Db、Ua等他抗原。【予防失敗要因】(1)妊娠最終月の抗体スクリーニング未実施、(2)抗体陽性母馬での母乳継続、(3)Mule妊娠での無検査、(4)分娩監視不在(初乳摂取制限機会逸失)、(5)前回NI歴の記録不在"
    ),
