        treatment_protocol="腎支持・利尿のための輸液療法(乳酸リンゲル液、0.9% NaCl)。尿路感染症には尿培養感受性試験に基づく抗菌薬。食事管理：炭酸カルシウム尿石症にはカルシウム摂取量を制限。外科的治療：膀胱結石に膀胱切開術、閉塞性尿石症に尿道瘻造設術。馬では尿の酸性化は一般的に無効。モニタリング：連続的な尿検査、BUN/クレアチニン、電解質。慢性腎不全：支持療法、食事性タンパク質の管理。",
