# ---------------------------------------------------------------------------
# Enrich horse diseases from diseases_all_species.json
# ---------------------------------------------------------------------------
def _enrich_horse_diseases() -> None:
    """Fill empty dataclass fields from the JSON database."""
    import json
    import os
    db_path = os.path.join(
        os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))),
        "diseases_all_species.json",
    )
    try:
        with open(db_path, encoding="utf-8") as f:
            all_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return
    lookup: dict[str, dict] = {}
    for entry in all_data:
        if entry.get("species") == "Horse":
            lookup[entry.get("name", "")] = entry

    # Prefer Japanese _ja fields from the enrichment JSON. The non-_ja keys contain
    # generic English templates; _ja keys contain curated Japanese clinical text.
    field_map = {
        "pathophysiology": ("pathophysiology_ja", "pathophysiology"),
        "etiology": ("causes_ja", "causes"),
        "treatment_protocol": ("treatment_ja", "treatment"),
        "prevention": ("prevention_ja", "prevention"),
        "prognosis": ("prognosis_ja", "prognosis"),
        "clinical_signs_detail": ("clinical_signs_ja", "clinical_signs"),
        "risk_factors": ("causes_ja", "causes"),
    }
    for disease in DISEASE_DATABASE:
        enrichment = lookup.get(disease.name_en)
        if enrichment:
            for dc_field, json_fields in field_map.items():
                if getattr(disease, dc_field, None):
                    continue
                for jf in json_fields:
                    val = enrichment.get(jf)
                    if val:
                        setattr(disease, dc_field, val)
                        break
            if not disease.general_management:
                val = enrichment.get("treatment_ja") or enrichment.get("treatment")
                if val:
                    disease.general_management = val
        # Fallback: generate content from existing description for unmatched diseases
        name = disease.name_en or disease.name_ja
        desc = disease.description_ja or disease.name_ja
        ja_name = disease.name_ja or name
        if not disease.pathophysiology:
            disease.pathophysiology = (
                f"{ja_name}は馬の組織に病理学的変化を引き起こす疾患である。"
                f"{desc} 未治療の場合、細胞障害、炎症反応、組織損傷の段階を経て進行しうる。"
            )
        if not disease.etiology:
            disease.etiology = (
                f"馬における{ja_name}の原因には、遺伝的素因、体型、"
                f"運動負荷、環境、飼養管理に関連する要因が含まれる。{desc}"
            )
        if not disease.treatment_protocol and not disease.general_management:
            disease.general_management = (
                f"馬における{ja_name}の管理は、原因への対処、適切な支持療法、"
                f"獣医師の指導に基づく治療的介入を行う。"
            )
        if not disease.prevention:
            disease.prevention = (
                "適切な飼養管理、定期的な獣医師による健康診断、バランスの取れた栄養管理、"
                "適度な運動、安全な飼養環境の維持が予防に重要である。"
            )
        if not disease.prognosis:
            disease.prognosis = (
                "予後は重症度、診断の時期、治療への反応に依存する。"
                "早期発見と適切な介入により転帰が改善する。"
            )


_enrich_horse_diseases()

# ルックアップ用辞書
_DISEASE_BY_ID: dict[str, Disease] = {d.id: d for d in DISEASE_DATABASE}


def get_disease(disease_id: str) -> Disease | None:
    return _DISEASE_BY_ID.get(disease_id)


def get_diseases_by_category(category: str) -> list[Disease]:
    return [d for d in DISEASE_DATABASE if d.category == category]


def get_all_categories() -> list[str]:
    seen: list[str] = []
    for d in DISEASE_DATABASE:
        if d.category not in seen:
            seen.append(d.category)
    return seen


