# 鑑別診断エンジン
# ====================================================================
CATEGORY_LABELS = {
    # Disease categories
    "musculoskeletal": ("運動器", "Musculoskeletal"),
    "hoof": ("蹄", "Hoof"),
    "digestive": ("消化器", "Digestive"),
    "respiratory": ("呼吸器", "Respiratory"),
    "infectious": ("感染症", "Infectious"),
    "skin": ("皮膚", "Skin"),
    "eye": ("眼", "Eye"),
    "neurological": ("神経系", "Neurological"),
    "metabolic": ("代謝性", "Metabolic"),
    "cardiovascular": ("循環器", "Cardiovascular"),
    "dental": ("歯科", "Dental"),
    "reproductive": ("生殖器", "Reproductive"),
    "toxic": ("中毒・毒性", "Toxic / Poisoning"),
    "foal": ("子馬", "Foal / Neonatal"),
    "immune": ("免疫", "Immune / Allergic"),
    "oncology": ("腫瘍", "Oncology"),
    "urinary": ("泌尿器", "Urinary"),
    "misc": ("その他", "Other / Environmental"),
    # Health check item categories
    "general": ("全身状態", "General"),
    "body": ("馬体", "Body"),
    "limb": ("肢・関節", "Limbs & Joints"),
    "repository_exam": ("レポジトリ検査", "Repository Exam"),
}


@dataclass
class DifferentialItem:
    """鑑別診断の1項目"""

    disease: Disease
    match_count: int  # 一致した所見数
    match_ratio: float  # 一致率 (0.0 - 1.0)
    matched_findings: list[str]  # 一致した所見キー
    confidence_pct: float = 0.0  # 信頼度 % (0-100)
    confidence_level: str = "low"  # "high" / "medium" / "low"
    weighted_score: float = 0.0  # IDF重み付きスコア
    # ── ベイズ除外診断情報 ──
    absence_penalty: float = 0.0  # 所見不在によるペナルティ (0.0-1.0)
    absent_key_findings: list[str] = field(default_factory=list)  # 不在の重要所見
    rule_out_note: str = ""  # 除外根拠の説明


# ====================================================================
# IDF (Inverse Disease Frequency) 重み計算
# 稀な所見ほど高い弁別力 → 高い重み
# ====================================================================
import math as _math


def _build_finding_idf() -> dict[str, float]:
    """各所見の IDF 重みを計算。log(N / df) で稀な所見ほど高値。"""
    n_diseases = len(DISEASE_DATABASE)
    df: dict[str, int] = {}  # document frequency
    for d in DISEASE_DATABASE:
        for f in d.associated_findings:
            df[f] = df.get(f, 0) + 1
    idf: dict[str, float] = {}
    for key, count in df.items():
        idf[key] = _math.log(n_diseases / count)
    return idf


# 起動時に1回計算(O(N))
_FINDING_IDF: dict[str, float] = _build_finding_idf()

# 所見ID → 日本語ラベル逆引き辞書
_FINDING_LABEL_JA: dict[str, str] = {}
for _cat_items in HEALTH_CHECK_ITEMS.values():
    for _fid, _ja, _en in _cat_items:
        _FINDING_LABEL_JA[_fid] = _ja

# IDF統計(正規化用)
_IDF_MAX = max(_FINDING_IDF.values()) if _FINDING_IDF else 1.0
_IDF_MIN = min(_FINDING_IDF.values()) if _FINDING_IDF else 0.0


def _confidence_level(pct: float) -> str:
    """信頼度%から high/medium/low を判定"""
    if pct >= 65.0:
        return "high"
    elif pct >= 35.0:
        return "medium"
    return "low"


def generate_differential_diagnosis(
    checked_findings: set[str],
    age_stage: str = "",
) -> list[DifferentialItem]:
    """IDF重み付き鑑別診断エンジン v2.0

    スコアリング:
      1. 各所見の IDF 重み = log(N / df)
         → gen_fever (103疾患) = 1.64, neuro_nystagmus (1疾患) = 6.27
      2. 疾患スコア = Σ(マッチした所見の IDF) / Σ(疾患全所見の IDF)
         → 稀な所見が一致するほど高スコア
      3. 信頼度 = スコア × マッチ数補正 × 年齢補正
         → 2所見以上でボーナス(組合せ評価)

    Args:
        checked_findings: チェックされた所見キーの集合
        age_stage: "young" / "adult" / "senior" / ""

    Returns:
        信頼度の高い順にソートされた鑑別診断リスト
    """
    if not checked_findings:
        return []

    results: list[DifferentialItem] = []

    for disease in DISEASE_DATABASE:
        if not disease.associated_findings:
            continue

        disease_findings = set(disease.associated_findings)
        matched = checked_findings & disease_findings
        match_count = len(matched)

        if match_count == 0:
            continue

        # --- IDF 重み付きスコア ---
        # 疾患の全所見の IDF 合計(満点)
        total_idf = sum(_FINDING_IDF.get(f, 1.0) for f in disease_findings)
        # マッチした所見の IDF 合計(獲得点)
        matched_idf = sum(_FINDING_IDF.get(f, 1.0) for f in matched)

        # 基本スコア: 重み付きマッチ率 (0.0 - 1.0)
        weighted_ratio = matched_idf / total_idf if total_idf > 0 else 0.0

        # --- 組合せボーナス (match_count が多いほど信頼度上昇) ---
        # 2所見: ×1.0, 3所見: ×1.08, 4所見: ×1.15, 5+: ×1.20
        combo_bonus = 1.0
        if match_count >= 5:
            combo_bonus = 1.20
        elif match_count >= 4:
            combo_bonus = 1.15
        elif match_count >= 3:
            combo_bonus = 1.08

        # --- ノイズ抑制 ---
        if match_count == 1:
            if len(disease_findings) >= 3:
                # 大きな疾患に1所見だけマッチ → 信頼度を大幅に下げる
                combo_bonus = 0.5
            elif len(disease_findings) == 1:
                # 1所見疾患 → IDF が低い(汎用所見)ならペナルティ
                the_finding = next(iter(disease_findings))
                finding_idf = _FINDING_IDF.get(the_finding, 3.0)
                # IDF < 3.0(≒20+疾患に出現)は信頼度を下げる
                if finding_idf < 3.0:
                    combo_bonus = 0.55
                elif finding_idf < 4.0:
                    combo_bonus = 0.75

        # --- 年齢適合ボーナス ---
        age_bonus = 1.0
        if age_stage and disease.age_predisposition and disease.age_predisposition == age_stage:
            age_bonus = 1.12

        # --- ベイズ除外診断: 所見の不在によるペナルティ ---
        # 理論: ユーザーが十分な数の所見をチェック(≥3)している場合、
        # 疾患の特徴的な所見(高IDF)が存在しないことは、
        # その疾患の事後確率を下げるべき情報である。
        #
        # P(D|absent_finding) ∝ P(D) × (1 - P(finding|D) × observability)
        # observability: その所見がユーザーに観察可能だった確率
        #   → ユーザーが多くの所見をチェックしている ≈ 観察が徹底的
        absence_penalty = 0.0
        absent_key_findings: list[str] = []

        n_checked = len(checked_findings)
        if n_checked >= 3 and len(disease_findings) >= 3:
            # 疾患の所見のうち未チェック(不在)の高IDF所見を特定
            absent = disease_findings - matched
            for f in absent:
                f_idf = _FINDING_IDF.get(f, 1.0)
                # IDF ≥ 4.0 の特徴的所見が不在 → 除外根拠
                if f_idf >= 4.0:
                    absent_key_findings.append(f)

            if absent_key_findings:
                # 観察徹底度: ユーザーがチェックした所見数に応じた重み
                # 3所見: 0.3, 5所見: 0.5, 8+所見: 0.7 (最大)
                observability = min(0.7, n_checked * 0.1)

                # 不在ペナルティ: 不在の高IDF所見の重みに比例
                absent_idf_sum = sum(_FINDING_IDF.get(f, 1.0) for f in absent_key_findings)
                max_penalty = absent_idf_sum / (total_idf + 1.0)
                absence_penalty = min(0.35, max_penalty * observability)

        # --- 最終スコア ---
        raw_score = weighted_ratio * combo_bonus * age_bonus * (1.0 - absence_penalty)

        # 信頼度 % (0-100) に変換
        # raw_score は理論上 0.0-1.2 の範囲なので 100 でスケール
        confidence_pct = min(99.0, round(raw_score * 100.0, 1))

        # 除外根拠の説明文生成
        rule_out_note = ""
        if absent_key_findings and absence_penalty > 0.05:
            absent_labels = []
            for f in absent_key_findings[:3]:
                lbl = _FINDING_LABEL_JA.get(f)
                if lbl:
                    absent_labels.append(lbl)
                else:
                    absent_labels.append(f)
            rule_out_note = f"特徴的所見の不在: {', '.join(absent_labels)}"

        # 旧互換: match_ratio も残す
        match_ratio = match_count / len(disease_findings)
        if age_stage and disease.age_predisposition == age_stage:
            match_ratio = min(1.0, match_ratio * 1.15)

        results.append(
            DifferentialItem(
                disease=disease,
                match_count=match_count,
                match_ratio=round(match_ratio, 3),
                matched_findings=sorted(matched),
                confidence_pct=confidence_pct,
                confidence_level=_confidence_level(confidence_pct),
                weighted_score=round(raw_score, 4),
                absence_penalty=round(absence_penalty, 3),
                absent_key_findings=sorted(absent_key_findings),
                rule_out_note=rule_out_note,
            )
        )

    # --- ソート: 信頼度 → マッチ数 → 重症度 ---
    severity_order = {"critical": 0, "severe": 1, "moderate": 2, "mild": 3}
    results.sort(
        key=lambda x: (
            -x.confidence_pct,
            -x.match_count,
            severity_order.get(x.disease.severity, 4),
        )
    )

    return results
